INSERT INTO parametro (nome, valor) VALUES ('total_exigido', 200), ('minimo_categorias', 2);
INSERT INTO interpretacao (ordem, texto) VALUES (1, 'Categorias para o mínimo de 2 (Art. 9º): as Categorias I a V do Art. 6º/Anexo A, não os tipos I a VIII listados no Art. 6º.');
INSERT INTO interpretacao (ordem, texto) VALUES (2, 'Itens do adendo: o adendo diz só ''Categoria III'' e não indica subcategoria; ficam na subcategoria III-A (criada aqui), sem teto de subcategoria.');
INSERT INTO interpretacao (ordem, texto) VALUES (3, '''Carga horária comprovada, com limite de N'' é teto por unidade (por projeto, por evento, por disciplina); a coluna ''Limite Máximo'' é o teto do item.');
INSERT INTO interpretacao (ordem, texto) VALUES (4, 'Coinventor recebe 50% só nos itens em que o Anexo A escreve essa regra (patente, desenho industrial, marca); registro de software não tem a regra escrita.');
INSERT INTO interpretacao (ordem, texto) VALUES (5, 'Adendo vale para pedidos protocolados a partir de 25/05/2026 (data do protocolo, não da atividade).');
INSERT INTO interpretacao (ordem, texto) VALUES (6, 'O adendo estende ''concursos'' a olimpíadas e maratonas nos itens ''preexistentes na Categoria III'', mas o item de participação em concurso fica na Categoria I (I-II). O cálculo aceita maratona nesse item; o texto não resolve a questão.');
INSERT INTO interpretacao (ordem, texto) VALUES (7, 'Estágio: a exigência ''mínimo de 20 mensais'' não tem unidade no texto e não é aplicada pelo cálculo.');
